function canJump(nums: number[]): boolean {
  // Самый дальний индекс, до которого точно можно добраться
  let farthest = 0;

  for (let i = 0; i < nums.length; i++) {
    // Индекс i недостижим — значит, и все дальше тоже
    if (i > farthest) return false;

    // Из i можно допрыгнуть до i + nums[i] — расширяем зону досягаемости
    farthest = Math.max(farthest, i + nums[i]);

    // Последний индекс уже в зоне досягаемости
    if (farthest >= nums.length - 1) return true;
  }

  return true;
}

// Время: O(n) — один проход
// Память: O(1)
